import { serve } from 'https://deno.land/std@0.208.0/http/server.ts';
import { createClient, SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';

// ---- _shared/supabase.ts ---------------------------------------------------------------------
function getServiceClient(): SupabaseClient {
  return createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
  );
}

/**
 * Connection string for functions that talk raw Postgres (deno-postgres / pg).
 * At 1000+ tenants you MUST go through Supavisor in TRANSACTION mode (port 6543)
 * so a burst of concurrent functions doesn't exhaust backend connections.
 * Set SUPABASE_DB_POOL_URL to the "Transaction pooler" URI from
 * Dashboard -> Project Settings -> Database. Falls back to the direct URL.
 * RLS in v2 reads the JWT (no session GUCs) so transaction pooling is safe.
 */
function getPooledConnectionString(): string {
  return (
    Deno.env.get('SUPABASE_DB_POOL_URL') ??
    Deno.env.get('SUPABASE_DB_URL') ??
    ''
  );
}

function corsHeaders(origin = '*') {
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-tenant-id, x-environment',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  };
}

function jsonResponse(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders(), 'Content-Type': 'application/json' },
  });
}

function errorResponse(message: string, status = 400) {
  return jsonResponse({ error: message }, status);
}

// resolveTenantContext (trusted X-Tenant-Id) and validateApiKey (prefix-only check) were
// removed in Phase 0 (SEC-02 / SEC-04). Use _shared/auth.ts for signed-in users, or
// _shared/ingest-auth.ts (API keys via verify_api_key, site keys via resolve_ingest_site).

// ---- _shared/auth.ts ---------------------------------
// Shared caller authentication for edge functions (Phase 0, SEC-01).
//
// Rule (docs/cpo/09-security-baseline.md §2): a function derives tenant access
// from a VERIFIED credential, never from a header or body. For calls made by a
// signed-in app user, the safest pattern is to act AS that user: queries run
// through a client carrying the user's JWT, so Postgres RLS enforces tenant
// isolation even if function code has a bug. Use the service role only after
// authentication, and only for work RLS can't express.


class AuthError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

type AuthedUser = {
  userId: string;
  email: string | null;
  /** Client that runs every query as the caller — RLS applies. */
  db: SupabaseClient;
};

const AUTH_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireEnv(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new AuthError(500, `Server misconfigured: ${name} is not set`);
  return v;
}

/** Verify the bearer token belongs to a real signed-in user (not the anon key). */
async function authenticateUser(req: Request): Promise<AuthedUser> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');

  const db = createClient(requireEnv('SUPABASE_URL'), requireEnv('SUPABASE_ANON_KEY'), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // getUser validates signature + expiry with Auth; the anon key has no user and fails here.
  const { data, error } = await db.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');

  return { userId: data.user.id, email: data.user.email ?? null, db };
}

/** Confirm the caller is an active member of the tenant (checked by the database as the caller). */
async function requireTenantMember(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (typeof tenantId !== 'string' || !AUTH_UUID_RE.test(tenantId)) throw new AuthError(400, 'tenant_id must be a UUID');
  const { data, error } = await user.db.rpc('user_has_tenant_access', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant membership check failed', error.message);
    throw new AuthError(500, 'Could not verify tenant access');
  }
  if (data !== true) throw new AuthError(403, 'No access to this tenant');
  return tenantId.toLowerCase();
}

/** Tenant named by the caller (membership verified), or the caller's own active membership. */
async function resolveTenant(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (tenantId !== undefined && tenantId !== null && tenantId !== '') return requireTenantMember(user, tenantId);
  const { data, error } = await user.db.from('tenant_users').select('tenant_id')
    .eq('user_id', user.userId).eq('status', 'active').order('created_at').limit(1);
  if (error) throw new AuthError(500, 'Could not resolve your workspace');
  const t = data?.[0]?.tenant_id as string | undefined;
  if (!t) throw new AuthError(403, 'You are not a member of any workspace');
  return t;
}

/** Throws 403 unless the caller holds `permission` in the tenant (tenant admins hold all). */
async function requirePermission(user: AuthedUser, tenantId: string, permission: string, label?: string): Promise<void> {
  const { data, error } = await user.db.rpc('user_has_permission', { p_tenant_id: tenantId, p_permission: permission });
  if (error) throw new AuthError(500, 'Could not verify permissions');
  if (data !== true) throw new AuthError(403, `You need the "${label ?? permission}" permission for this`);
}

// ---- _shared/ingest-auth.ts ------------------------------------------------------------------
// Authentication for PUBLIC ingest endpoints (Phase 0, SEC-02).
//
// Two credential types — tenant/environment always come from the credential, never the request:
//   • Secret API key (server-to-server): `x-api-key: mk_…` or `Authorization: Bearer mk_…`.
//     Verified by public.verify_api_key() (bcrypt). Must carry the required scope.
//   • Site key (browser SDKs): body `site_id` + `write_key` (public by design, like a
//     Segment write key). Verified by public.resolve_ingest_site(): key, site status and
//     the browser Origin against the site's domain / allowed_origins.
//
// Because a site key is public, it can be copied and replayed from a script. Defences:
// per-site + per-IP rate limits here (per isolate — a backstop), frequency caps at send
// time (Wave 1 guardrails), and identity verification for identified users (SEC-13).


type IngestContext = {
  tenantId: string;
  environment: string;
  via: 'api_key' | 'site_key';
  siteId?: string;
  siteUuid?: string;
};

/** Read the secret API key if one was sent. JWTs (anon/user tokens) are ignored here. */
function readApiKey(req: Request): string | null {
  const header = req.headers.get('x-api-key')?.trim();
  if (header) return header;
  const auth = req.headers.get('authorization') ?? '';
  const bearer = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
  // Supabase JWTs have three dot-separated parts; Marbee API keys don't.
  if (bearer && bearer.split('.').length !== 3) return bearer;
  return null;
}

async function authenticateApiKey(db: SupabaseClient, rawKey: string, scope: string): Promise<IngestContext> {
  const { data, error } = await db.rpc('verify_api_key', { p_raw_key: rawKey });
  if (error) {
    console.error('verify_api_key failed', error.message);
    throw new AuthError(500, 'Could not verify API key');
  }
  const row = Array.isArray(data) ? data[0] : null;
  if (!row) throw new AuthError(401, 'Invalid or revoked API key');
  const scopes: string[] = row.scopes ?? [];
  if (!scopes.includes(scope) && !scopes.includes('*')) throw new AuthError(403, `API key is missing the ${scope} scope`);
  return { tenantId: row.tenant_id, environment: row.environment ?? 'production', via: 'api_key' };
}

async function authenticateSiteKey(
  db: SupabaseClient,
  siteId: unknown,
  writeKey: unknown,
  origin: string | null,
): Promise<IngestContext> {
  if (typeof siteId !== 'string' || typeof writeKey !== 'string') {
    throw new AuthError(401, 'site_id and write_key are required');
  }
  const { data, error } = await db.rpc('resolve_ingest_site', {
    p_site_id: siteId, p_write_key: writeKey, p_origin: origin,
  });
  if (error) {
    console.error('resolve_ingest_site failed', error.message);
    throw new AuthError(500, 'Could not verify site key');
  }
  const r = data as { ok: boolean; reason?: string; tenant_id?: string; environment?: string; site_id?: string; site_uuid?: string };
  if (!r?.ok) {
    const status = r?.reason === 'invalid_key' ? 401 : 403;
    const message = r?.reason === 'origin_not_allowed'
      ? 'This website is not allowed to use this site key'
      : r?.reason === 'tenant_suspended' ? 'This workspace is suspended'
      : r?.reason?.startsWith('site_') ? 'Site is not active' : 'Invalid site key';
    throw new AuthError(status, message);
  }
  return { tenantId: r.tenant_id!, environment: r.environment ?? 'production', via: 'site_key', siteId: r.site_id, siteUuid: r.site_uuid };
}

/** API key if present, otherwise site key from the parsed body. */
async function authenticateIngest(
  req: Request,
  db: SupabaseClient,
  body: Record<string, unknown> | null,
  scope: string,
): Promise<IngestContext> {
  const apiKey = readApiKey(req);
  if (apiKey) return authenticateApiKey(db, apiKey, scope);
  return authenticateSiteKey(db, body?.site_id, body?.write_key, req.headers.get('origin'));
}

// --------------------------------------------------------------------------------------
// Rate limit — fixed window per isolate. A backstop against floods, not a billing meter.
// --------------------------------------------------------------------------------------
const windows = new Map<string, { start: number; count: number }>();

function rateLimited(key: string, max: number, windowMs = 60_000): boolean {
  const now = Date.now();
  const w = windows.get(key);
  if (!w || now - w.start >= windowMs) {
    windows.set(key, { start: now, count: 1 });
    if (windows.size > 10_000) windows.clear(); // bound memory
    return false;
  }
  w.count += 1;
  return w.count > max;
}

function clientIp(req: Request): string {
  return req.headers.get('cf-connecting-ip')
    ?? req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    ?? 'unknown';
}

/** Reject oversized bodies before parsing (Content-Length when present). */
function tooLarge(req: Request, maxBytes: number): boolean {
  const len = Number(req.headers.get('content-length') ?? 0);
  return Number.isFinite(len) && len > maxBytes;
}

// ---- _shared/webhook-sig.ts ------------------------------------------------------------------
// Constant-time compare + HMAC signature verification (Phase 0 · SEC-18).
// No imports, so it is easy to test and safe to share.

function constantTimeEqual(a: string, b: string): boolean {
  const ea = new TextEncoder().encode(a);
  const eb = new TextEncoder().encode(b);
  let diff = ea.length ^ eb.length;
  for (let i = 0; i < Math.max(ea.length, eb.length); i += 1) diff |= (ea[i] ?? 0) ^ (eb[i] ?? 0);
  return diff === 0;
}

/** HMAC-SHA* of `body` (the exact raw bytes received) with `secret`, as lowercase hex and base64. */
async function hmacDigests(secret: string, body: string | Uint8Array, algorithm: string): Promise<{ hex: string; b64: string }> {
  const algo = algorithm.toUpperCase();
  const hash = algo === 'SHA512' ? 'SHA-512' : algo === 'SHA1' ? 'SHA-1' : 'SHA-256';
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash }, false, ['sign']);
  const bytes: Uint8Array<ArrayBuffer> = typeof body === 'string' ? new TextEncoder().encode(body) : new Uint8Array(body);
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, bytes));
  const hex = Array.from(sig, (b) => b.toString(16).padStart(2, '0')).join('');
  let bin = '';
  for (const b of sig) bin += String.fromCharCode(b);
  return { hex, b64: btoa(bin) };
}

/**
 * Verify a webhook signature header. Accepts bare hex, bare base64, or
 * "<algo>=<hex>" (e.g. GitHub's "sha256=…"). Constant-time compare.
 */
async function verifyHmacSignature(secret: string, body: string | Uint8Array, algorithm: string, provided: string): Promise<boolean> {
  if (!secret || !provided) return false;
  const value = provided.trim().replace(/^(sha1|sha256|sha512)=/i, '');
  const { hex, b64 } = await hmacDigests(secret, body, algorithm);
  return constantTimeEqual(value.toLowerCase(), hex) || constantTimeEqual(value, b64);
}

// ---- _shared/tenant-guard.ts -----------------------------------------------------------------
// Workspace guards for edge functions that act with the service role
// (Phase 0 · TD-12b, SEC-18).
//
// sql/91 makes suspension automatic for anything that goes through RLS or the
// permission helpers. Functions that use the service role and find the tenant
// themselves (a form id, a bot id, a webhook path, an asset id) must call
// assertTenantActive() once they know the tenant. All checks fail CLOSED: if the
// database can't answer, the request is refused.


/** True only if the tenant exists and is not suspended. */
async function tenantIsActive(service: SupabaseClient, tenantId: string): Promise<boolean> {
  const { data, error } = await service.rpc('tenant_is_active', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant_is_active failed', error.message);
    throw new AuthError(503, 'Workspace check unavailable — try again shortly');
  }
  return data === true;
}

/** Throws 403 "This workspace is suspended" (or 503 if the check can't run). */
async function assertTenantActive(service: SupabaseClient, tenantId: string): Promise<void> {
  if (!(await tenantIsActive(service, tenantId))) throw new AuthError(403, 'This workspace is suspended');
}

/** True when the caller presented the project's service-role key (internal engine calls). */
function isServiceCaller(req: Request): boolean {
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  return key.length > 0 && token.length > 0 && constantTimeEqual(token, key);
}

/**
 * Signed-in user who is an ACTIVE member of an ACTIVE tenant and holds one of
 * `permissions` (tenant admins hold all). Returns the user id; throws AuthError.
 */
async function requireMemberWithPermission(
  service: SupabaseClient,
  req: Request,
  tenantId: string,
  permissions: string[],
): Promise<string> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');
  const { data, error } = await service.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');
  for (const permission of permissions) {
    const { data: ok, error: permErr } = await service.rpc('user_has_permission_as', {
      p_user_id: data.user.id, p_tenant_id: tenantId, p_permission: permission,
    });
    if (permErr) {
      console.error('user_has_permission_as failed', permErr.message);
      throw new AuthError(503, 'Permission check unavailable — try again shortly');
    }
    if (ok === true) return data.user.id;
  }
  throw new AuthError(403, 'You do not have permission for this in this workspace');
}

// ---- webhook-trigger/index.ts ----------------------------------------------------------------
// Webhook Trigger — receives inbound HTTP requests and kicks off the matching
// pipeline run. Supports every HTTP method, authentication modes, CORS,
// IP allowlisting, bot filtering, idempotency, and configurable responses.
//
//   ANY /functions/v1/webhook-trigger/<path-uuid>
//
// The <path-uuid> matches the `path` config field on a trigger_webhook node
// inside an active data_job's workflow_json.
//
// Phase 0 (SEC-18 / TD-12b): auth modes now really verify — api_key/bearer use a
// Marbee API key (verify_api_key, same workspace + environment, scope
// custom_api:invoke); hmac verifies the signature over the raw body; basic, oauth2
// and unknown modes are refused. Credential headers are never stored with the run.
// Suspended workspaces are refused.


const json = (d: unknown, s = 200, headers: Record<string, string> = {}) =>
  new Response(JSON.stringify(d), {
    status: s,
    headers: { ...corsHeaders(), 'Content-Type': 'application/json', ...headers },
  });

const text = (body: string, s = 200, ct = 'text/plain', headers: Record<string, string> = {}) =>
  new Response(body, { status: s, headers: { ...corsHeaders(), 'Content-Type': ct, ...headers } });

// Never persist credentials that arrive with the request.
const SENSITIVE_HEADERS = /^(authorization|cookie|x-api-key|apikey|proxy-authorization|x-signature|x-hub-signature(-256)?)$/i;
const MAX_BODY_BYTES = 5 * 1024 * 1024;

const BOT_PATTERNS = /bot|crawler|spider|slurp|mediapartners|facebookexternalhit|bingpreview|linkedinbot/i;

serve(async (req) => {
  const supabase = getServiceClient();

  // Extract the webhook path from the URL — everything after /webhook-trigger/
  const url = new URL(req.url);
  const segments = url.pathname.split('/webhook-trigger/');
  const webhookPath = segments[1]?.replace(/^\/+|\/+$/g, '') ?? '';

  if (!webhookPath) {
    return json({ error: 'Missing webhook path' }, 400);
  }

  // --- Look up the data_job that owns this webhook path ---
  // We search workflow_json for a trigger_webhook node whose config.path matches.
  const { data: jobs, error: lookupErr } = await supabase
    .from('data_jobs')
    .select('id, tenant_id, environment, workflow_json, current_version')
    .eq('status', 'active');

  if (lookupErr) return json({ error: 'Lookup failed' }, 500);

  // Find the job + node whose trigger_webhook config.path matches
  let matchedJob: typeof jobs[0] | null = null;
  let webhookConfig: Record<string, unknown> = {};

  for (const job of jobs ?? []) {
    const wf = job.workflow_json as { nodes?: Array<{ data?: { stepType?: string; config?: Record<string, unknown> } }> };
    const nodes = wf?.nodes ?? [];
    for (const node of nodes) {
      const st = node.data?.stepType;
      if ((st === 'trigger_webhook' || st === 'webhook') && node.data?.config?.path === webhookPath) {
        matchedJob = job;
        webhookConfig = node.data.config;
        break;
      }
    }
    if (matchedJob) break;
  }

  if (!matchedJob) {
    return json({ error: 'No active pipeline found for this webhook path' }, 404);
  }

  try {
    await assertTenantActive(supabase, matchedJob.tenant_id);
  } catch (e) {
    const status = e instanceof AuthError ? e.status : 503;
    return json({ error: e instanceof Error ? e.message : 'Workspace check failed' }, status);
  }

  // --- CORS preflight ---
  const allowedOrigins = String(webhookConfig.allowed_origins ?? '');
  const origin = req.headers.get('origin') ?? '';
  if (req.method === 'OPTIONS') {
    const corsH: Record<string, string> = { ...corsHeaders() };
    if (allowedOrigins) {
      const allowed = allowedOrigins.split(',').map(s => s.trim());
      corsH['Access-Control-Allow-Origin'] = allowed.includes(origin) ? origin : allowed[0];
    }
    corsH['Access-Control-Allow-Methods'] = 'GET, POST, PUT, PATCH, DELETE, OPTIONS';
    return new Response('ok', { headers: corsH });
  }

  // --- Method check ---
  const expectedMethod = String(webhookConfig.method ?? 'POST').toUpperCase();
  if (req.method !== expectedMethod && req.method !== 'OPTIONS') {
    return json({ error: `Expected ${expectedMethod}, got ${req.method}` }, 405);
  }

  // --- Bot filtering ---
  if (webhookConfig.ignore_bots === true) {
    const ua = req.headers.get('user-agent') ?? '';
    if (BOT_PATTERNS.test(ua)) {
      return json({ error: 'Bot requests are ignored' }, 403);
    }
  }

  // --- IP allowlist ---
  const ipAllowlist = String(webhookConfig.ip_allowlist ?? '');
  if (ipAllowlist) {
    const clientIp = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
      ?? req.headers.get('x-real-ip')
      ?? 'unknown';
    const allowed = ipAllowlist.split(',').map(s => s.trim());
    const ipMatch = allowed.some(range => {
      if (range.includes('/')) {
        return cidrContains(range, clientIp);
      }
      return range === clientIp;
    });
    if (!ipMatch) {
      return json({ error: 'IP not in allowlist' }, 403);
    }
  }

  // --- Raw body (read once: HMAC must be computed over the exact bytes received) ---
  const configuredMax = Number(webhookConfig.max_payload_size) || 1024 * 1024;
  const maxBytes = Math.min(Math.max(configuredMax, 1024), MAX_BODY_BYTES);
  if (Number(req.headers.get('content-length') ?? 0) > maxBytes) return json({ error: 'Payload too large' }, 413);
  const hasBody = req.method !== 'GET' && req.method !== 'HEAD';
  const rawBytes = hasBody ? new Uint8Array(await req.arrayBuffer()) : new Uint8Array();
  if (rawBytes.byteLength > maxBytes) return json({ error: 'Payload too large' }, 413);
  const bodyReq = new Request(req.url, {
    method: req.method,
    headers: req.headers,
    body: hasBody && rawBytes.byteLength ? rawBytes : undefined,
  });

  // --- Authentication ---
  const authMode = String(webhookConfig.auth ?? 'none');
  if (authMode !== 'none') {
    const authResult = await validateAuth(req, supabase, matchedJob, authMode, webhookConfig, rawBytes);
    if (!authResult.ok) {
      return json({ error: authResult.error ?? 'Authentication failed' }, authResult.status ?? 401);
    }
  }

  // --- Conditional execution ---
  const onlyRunIf = String(webhookConfig.only_run_if ?? '');
  if (onlyRunIf) {
    // Simple header-based condition: "headers.x-api-version == \"2\""
    // For now, log it but don't block (full expression eval is a future enhancement)
  }

  // --- Parse payload ---
  let payload: Record<string, unknown> = {};
  const contentType = String(webhookConfig.content_type ?? 'json');

  try {
    if (req.method === 'GET') {
      payload = Object.fromEntries(url.searchParams.entries());
    } else if (webhookConfig.raw_body === true) {
      payload = { body: new TextDecoder().decode(rawBytes), _raw: true };
    } else if (contentType === 'json' || req.headers.get('content-type')?.includes('json')) {
      payload = await bodyReq.json();
    } else if (contentType === 'form' || req.headers.get('content-type')?.includes('form-urlencoded')) {
      const form = await bodyReq.formData();
      form.forEach((v, k) => { payload[k] = String(v); });
    } else if (contentType === 'xml' || req.headers.get('content-type')?.includes('xml')) {
      payload = { body: new TextDecoder().decode(rawBytes), _content_type: 'xml' };
    } else if (contentType === 'multipart' || req.headers.get('content-type')?.includes('multipart')) {
      const form = await bodyReq.formData();
      const binaryField = String(webhookConfig.binary_field ?? 'file');
      form.forEach((v, k) => {
        if (v instanceof File) {
          payload[k] = { _file: true, name: v.name, size: v.size, type: v.type };
        } else {
          payload[k] = String(v);
        }
      });
    } else {
      payload = { body: new TextDecoder().decode(rawBytes) };
    }
  } catch {
    return json({ error: 'Failed to parse request body' }, 400);
  }

  // Enrich payload with request metadata
  const enrichedPayload = {
    ...payload,
    _webhook: {
      path: webhookPath,
      method: req.method,
      received_at: new Date().toISOString(),
      headers: Object.fromEntries([...req.headers.entries()].filter(([k]) => !SENSITIVE_HEADERS.test(k))),
      query: Object.fromEntries(url.searchParams.entries()),
      ip: req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? req.headers.get('x-real-ip') ?? null,
    },
  };

  // --- Idempotency check ---
  const idempotencyKeyField = String(webhookConfig.idempotency_key ?? '');
  let idempotencyKey: string | null = null;
  if (idempotencyKeyField) {
    idempotencyKey = String(payload[idempotencyKeyField] ?? req.headers.get(`x-${idempotencyKeyField}`) ?? '');
    if (idempotencyKey) {
      const { data: existing } = await supabase
        .from('data_job_runs')
        .select('id, status')
        .eq('job_id', matchedJob.id)
        .eq('trigger_source', 'webhook')
        .contains('trigger_payload', { [idempotencyKeyField]: payload[idempotencyKeyField] })
        .in('status', ['queued', 'running', 'succeeded'])
        .limit(1);
      if (existing?.length) {
        return json({
          status: 'duplicate',
          message: `Request already processed (idempotency key: ${idempotencyKeyField}=${idempotencyKey})`,
          run_id: existing[0].id,
          run_status: existing[0].status,
        }, 200);
      }
    }
  }

  // --- Create the run ---
  const { data: run, error: runErr } = await supabase
    .from('data_job_runs')
    .insert({
      job_id: matchedJob.id,
      tenant_id: matchedJob.tenant_id,
      environment: matchedJob.environment,
      status: 'queued',
      trigger_source: 'webhook',
      trigger_payload: enrichedPayload,
      run_mode: 'full',
    })
    .select('id')
    .single();

  if (runErr || !run) {
    return json({ error: 'Failed to create pipeline run' }, 500);
  }

  // --- Invoke the pipeline-run-worker ---
  const workerUrl = `${Deno.env.get('SUPABASE_URL')}/functions/v1/pipeline-run-worker`;
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';

  // Fire-and-forget for "immediately" respond mode
  const respond = String(webhookConfig.respond ?? 'immediately');

  const workerCall = fetch(workerUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${serviceKey}`,
    },
    body: JSON.stringify({ run_id: run.id }),
  });

  if (respond === 'last_node') {
    // Wait for the worker to finish, then return its result
    try {
      const workerResp = await workerCall;
      const workerResult = await workerResp.json();

      // Fetch the completed run for stats
      const { data: completedRun } = await supabase
        .from('data_job_runs')
        .select('status, stats, completed_at')
        .eq('id', run.id)
        .single();

      return buildResponse(webhookConfig, {
        status: 'completed',
        run_id: run.id,
        run_status: completedRun?.status ?? 'unknown',
        stats: completedRun?.stats ?? {},
      });
    } catch {
      return json({ error: 'Pipeline execution failed' }, 500);
    }
  }

  // "immediately" — fire and forget
  workerCall.catch(() => {});

  return buildResponse(webhookConfig, {
    status: 'accepted',
    run_id: run.id,
    message: 'Pipeline run queued',
  });
});

// --- Helpers ---

function buildResponse(
  config: Record<string, unknown>,
  defaultBody: Record<string, unknown>,
): Response {
  const noResponseBody = config.no_response_body === true;
  const responseCode = Number(config.response_code) || 200;
  const responseContentType = String(config.response_content_type ?? 'json');

  // Custom response headers
  let extraHeaders: Record<string, string> = {};
  try {
    const h = String(config.response_headers ?? '{}');
    if (h && h !== '{}') extraHeaders = JSON.parse(h);
  } catch {}

  // CORS origin header
  const allowedOrigins = String(config.allowed_origins ?? '');
  if (allowedOrigins) {
    const allowed = allowedOrigins.split(',').map(s => s.trim());
    extraHeaders['Access-Control-Allow-Origin'] = allowed[0];
  }

  if (noResponseBody) {
    return new Response(null, { status: responseCode >= 200 ? responseCode : 204, headers: { ...corsHeaders(), ...extraHeaders } });
  }

  // Custom response data
  const responseData = String(config.response_data ?? '');
  if (responseData) {
    const ct = responseContentType === 'html' ? 'text/html'
      : responseContentType === 'xml' ? 'application/xml'
      : responseContentType === 'text' ? 'text/plain'
      : 'application/json';
    // Replace simple {{field}} templates with values from defaultBody
    const resolved = responseData.replace(/\{\{(\w[\w.]*)\}\}/g, (_, k) =>
      String((defaultBody as Record<string, unknown>)[k] ?? k)
    );
    return text(resolved, responseCode, ct, extraHeaders);
  }

  return json(defaultBody, responseCode, extraHeaders);
}

type MatchedJob = { id: string; tenant_id: string; environment: string };

async function validateAuth(
  req: Request,
  supabase: ReturnType<typeof getServiceClient>,
  job: MatchedJob,
  mode: string,
  config: Record<string, unknown>,
  rawBody: Uint8Array,
): Promise<{ ok: boolean; error?: string; status?: number }> {
  switch (mode) {
    case 'bearer':
    case 'api_key': {
      const authHeader = req.headers.get('authorization') ?? '';
      const raw = mode === 'bearer'
        ? (authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '')
        : (req.headers.get('x-api-key') ?? '').trim(); // never from the URL: URLs end up in logs
      if (!raw) return { ok: false, error: mode === 'bearer' ? 'Missing Bearer token' : 'Missing x-api-key header' };
      try {
        const key = await authenticateApiKey(supabase, raw, 'custom_api:invoke');
        if (key.tenantId !== job.tenant_id || key.environment !== job.environment) {
          return { ok: false, error: 'API key is not valid for this webhook' };
        }
        return { ok: true };
      } catch (e) {
        return {
          ok: false,
          error: e instanceof Error ? e.message : 'Invalid API key',
          status: e instanceof AuthError ? e.status : 401,
        };
      }
    }
    case 'hmac': {
      const secret = String(config.hmac_secret ?? '');
      if (!secret) return { ok: false, error: 'Webhook HMAC secret is not configured', status: 500 };
      const headerName = String(config.hmac_header || 'X-Signature');
      const sig = req.headers.get(headerName) ?? req.headers.get('x-hub-signature-256') ?? '';
      if (!sig) return { ok: false, error: `Missing ${headerName} signature` };
      const valid = await verifyHmacSignature(secret, rawBody, String(config.hmac_algorithm || 'SHA256'), sig);
      return valid ? { ok: true } : { ok: false, error: 'Invalid signature' };
    }
    case 'basic':
    case 'oauth2':
      return {
        ok: false,
        error: `"${mode}" authentication is not supported for webhooks — use API key, Bearer token or HMAC`,
        status: 400,
      };
    default:
      return { ok: false, error: `Unknown authentication mode "${mode}"`, status: 400 };
  }
}

function cidrContains(cidr: string, ip: string): boolean {
  try {
    const [range, bits] = cidr.split('/');
    const mask = ~(2 ** (32 - Number(bits)) - 1) >>> 0;
    const ipNum = ipToNum(ip);
    const rangeNum = ipToNum(range);
    return (ipNum & mask) === (rangeNum & mask);
  } catch {
    return false;
  }
}

function ipToNum(ip: string): number {
  const parts = ip.split('.').map(Number);
  return ((parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]) >>> 0;
}
